import{_ as a,o as i,c as s,a6 as n}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Arquitectura y límites de la demo web","description":"","frontmatter":{"title":"Arquitectura y límites de la demo web","docId":"developer.demo","translationKey":"developer.demo","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"9884cf56b87f6ddb7a6a9331e144da20913db78eb4d6f764fbd00c7a17f00f31","translationRevision":"a40bc2d573a50630b29e15abbd0f0448e79380b1e9774c0f44e5037a95405802","order":140},"headers":[],"relativePath":"es/developer/demo.md","filePath":"es/developer/demo.md","lastUpdated":1794618099000}'),t={name:"es/developer/demo.md"};function o(r,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="browser-demo-architecture-and-limits" tabindex="-1">Arquitectura y límites de la demo web <a class="header-anchor" href="#browser-demo-architecture-and-limits" aria-label="Permalink to &quot;Arquitectura y límites de la demo web {#browser-demo-architecture-and-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Explora la interfaz real con datos sintéticos en un navegador. Usa Bun 1.4.4 y la instalación bloqueada del repositorio. La entrada explícita de la demo funciona sin Rust, cuentas ni host activo. Su runtime y las pruebas de navegador forman parte del repositorio.</p><h2 id="build-and-inspect" tabindex="-1">Compilar e inspeccionar <a class="header-anchor" href="#build-and-inspect" aria-label="Permalink to &quot;Compilar e inspeccionar {#build-and-inspect}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>Para previsualizar cambios sin commit usa <code>TIKTOOLS_SITE_ALLOW_DIRTY=1 bun scripts/task.ts site build</code>. El manifiesto se marca como dirty y publicación lo rechaza. El ensamblado final exige el mismo SHA Git limpio y base en ambos paquetes; vuelve a compilar después del commit. Inicia desarrollo o previsualización únicamente cuando quieras trabajar en el navegador local. <code>docs</code> posee VitePress y <code>demo</code> el paquete web de la aplicación; <code>site build</code> los reúne en un sitio estático. El workspace documental conserva su dependencia VitePress separada de Vite 8 de la aplicación. Las órdenes no deben instalar dependencias silenciosamente ni invocar Cargo.</p><h2 id="preserve-the-application-boundary" tabindex="-1">Conservar el límite de aplicación <a class="header-anchor" href="#preserve-the-application-boundary" aria-label="Permalink to &quot;Conservar el límite de aplicación {#preserve-the-application-boundary}&quot;">​</a></h2><p><code>src/web/app/mount-workspace.ts</code> proporciona la factoría compartida de aplicación/Pinia/router; importarla no monta ni selecciona transporte. El arranque demo explícito aporta <code>src/web/demo/runtime/transport.ts</code> al límite <code>ControlTransport</code>/cliente de control. Las muestras puras viven en <code>demo/fixtures/base-host.ts</code>, independientes de Playwright. <code>shared/lib/app-storage.ts</code> y <code>demo/storage.ts</code> aíslan almacenamiento para que reiniciar no borre preferencias nativas ni otra instancia demo. Páginas, widgets y funcionalidades deben utilizar sus almacenes y llamadas existentes en <code>src/web/shared/api</code>. No crees una segunda aplicación de imitación, no inyectes APIs nativas falsas en el arranque normal ni permitas que una solicitud demo termine en un host real.</p><p><code>demo/scenarios.ts</code> valida 11 escenarios y las rutas, idiomas y recorridos admitidos. <code>runtime/host.ts</code> registra handlers explícitos: discovery anuncia esos handlers, los IDs se conservan en <code>rpc-response</code> y los efectos no admitidos devuelven error inmediatamente. El host prepara datos ficticios y avanza un reloj fijo al pulsar Siguiente evento. Reproducir y Siguiente evento conectan primero al creador ficticio mediante el RPC simulado si hace falta y generan un evento inmediato. Reproducir continúa cada dos segundos; Pausar detiene la producción. La barra muestra el estado y el contador de eventos. El flujo termina a los 300 pasos y conserva hasta 60 eventos y 60 ejecuciones. Las colas de respuestas y registros tienen límites independientes.</p><p>Reiniciar limpia únicamente el prefijo <code>tiktools.demo.&lt;instance&gt;.*</code> y recarga el iframe. Recargar reinicializa singletons, journals, i18n y diagnósticos. Cada iframe recibe un identificador distinto. Al salir se desmonta Vue, se liberan stores, cliente y transporte, y se detienen ambos temporizadores. La demo no instala <code>window.ipc</code> ni realiza HTTP arbitrario, shell, RCON, ejecución de código visitante o actualización nativa. Su CSP rechaza conexiones de red. Las plantillas de log y filtros simulados usan funciones puras compartidas: representan el contrato del frontend y no sustituyen la ejecución Rust.</p><p>El parámetro <code>embed=connection|feed|automation|points|overlays</code> selecciona una vista incrustada enfocada. Oculta la navegación general y conserva las páginas y el runtime reales; utiliza la ruta correspondiente al panel, sin iniciar un recorrido guiado. La vista de conexión permite practicar los controles sin ocupar el artículo con todo el espacio de trabajo. El modo incrustado mantiene el mismo límite de transporte simulado y el aislamiento de almacenamiento de la demo completa.</p><p>Todos los iframes documentales utilizan <code>framed=1</code>, que oculta la barra grande <code>DemoToolbar</code>. <strong>Reproducir</strong>, <strong>Pausar</strong>, <strong>Siguiente evento</strong> y <strong>Reiniciar</strong> aparecen en una fila compacta del componente padre <code>DemoFrame</code>; la demo independiente conserva su barra completa. El puente de mensajes entre padre e iframe solo admite los controles previstos de reproducción, reinicio y selección de casos de recuperación de conexión, valida el origen, la ventana emisora (<code>source</code>) y el identificador de instancia, y no expone llamadas RPC arbitrarias. El transporte simulado y el almacenamiento aislado mantienen sus límites anteriores.</p><p>La entrada <code>startTour(id, {router, capabilities, taskState})</code> y el registro <code>tourRegistry</code> están en <code>src/web/features/guided-help/index.ts</code>. Siete recorridos versionados utilizan objetivos estables y catálogos separados para cada idioma admitido. Driver.js carga bajo demanda, limita objetivos al workspace, respeta movimiento reducido, restaura foco y cancela esperas acotadas al navegar. Cerrar una guía nunca completa tareas ni ejecuta acciones de la aplicación. El selector nombra la tarea completa, prepara su escenario y pausa la reproducción antes de iniciar. El cierre de Driver descarta la guía y la barra muestra el resultado. Reiniciar limpia el progreso versionado de esta instancia.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>La demo muestra navegación, edición local, eventos y recuperación que admite su modelo. No valida sesiones TikTok, OBS Browser Source, Wry/comportamiento nativo, backend de producción ni varios equipos. Rankings sigue oculto; Changes de Automations es local, Variables revisadas tiene implementación nativa real, Changes de Overlays es un seguimiento sin integrar y las puertas de instalación automática siguen experimentales.</p><h2 id="components-and-markdown" tabindex="-1">Componentes y Markdown <a class="header-anchor" href="#components-and-markdown" aria-label="Permalink to &quot;Componentes y Markdown {#components-and-markdown}&quot;">​</a></h2><p><code>docs/examples/*.vue</code> aporta el catálogo ejecutable y sus snippets. Los botones pequeños se montan directamente en Markdown sin estilos globales del escritorio. Los diálogos, layouts y páginas completas usan <code>DemoFrame</code>, que valida parámetros y respeta el base. En los artículos, el iframe se carga bajo demanda; la página de inicio lo carga automáticamente para mostrar la aplicación real. La opción pública <code>VITE_TIKTOOLS_PUBLIC_UI_KIT=1</code> expone el catálogo sin activar todas las herramientas de desarrollo del escritorio.</p><p>Para insertar un panel real junto a una instrucción, declara el escenario, idioma, panel y un título descriptivo:</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;es&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Practica tu primera conexión LIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><code>panel</code> admite <code>connection</code>, <code>feed</code>, <code>automation</code>, <code>points</code> y <code>overlays</code> y selecciona el modo <code>embed</code> correspondiente. En un artículo, antes de interactuar se muestra un marcador neutro con el título y el botón para probar el ejemplo, sin cargar el iframe. El botón carga la instancia aislada; reiniciar descarta únicamente el estado de esa instancia. <strong>Abrir demo completa</strong> sale del modo incrustado y recupera la navegación general. Coloca cada ejemplo junto al paso que explica y conserva el texto necesario para comprender la tarea sin cargarlo.</p><p>La página de inicio utiliza <code>autoload</code> para cargar el iframe real en cuanto se monta el componente y <code>minimal</code> para reducir la presentación auxiliar de <code>DemoFrame</code>, que ya proporciona el contenedor de la página. Los controles de reproducción permanecen en la fila compacta del padre. Las cinco pestañas comparten una sola vista activa: al cambiar de pestaña se desmonta el iframe anterior antes de mostrar el siguiente. No se utiliza <code>ScenePreview</code> ni una interfaz dibujada que imite la aplicación.</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;es&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Prueba TikTools&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> autoload</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> minimal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>El iframe conserva un viewport de escritorio de <code>1280</code> píxeles CSS de ancho. El contenedor aplica <code>transform: scale(...)</code> desde fuera: las consultas de medios de la aplicación siguen evaluándose con el ancho de escritorio, incluso cuando el artículo se ve en una pantalla estrecha. El ajuste automático adapta la escala al espacio disponible; también se puede elegir <code>25</code>, <code>50</code>, <code>75</code> o <code>100</code> %. Cambiar el zoom no recarga el iframe ni pierde el estado de la demo.</p><p>La prop opcional <code>scale</code> permite fijar una escala inicial y <code>viewportHeight</code> permite indicar la altura del viewport de escritorio. Por ejemplo:</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;es&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Prueba TikTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">viewport-height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">720</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>El contenedor reserva la altura escalada durante la carga para evitar saltos de contenido. Estas opciones de presentación no cambian el transporte simulado ni el aislamiento de almacenamiento y ciclo de vida de cada instancia.</p><h2 id="recovery-and-verification" tabindex="-1">Recuperación y verificación <a class="header-anchor" href="#recovery-and-verification" aria-label="Permalink to &quot;Recuperación y verificación {#recovery-and-verification}&quot;">​</a></h2><p>Reinicia el escenario después de simular un hueco o fallo. Si contacta con un servicio externo, detén el recorrido y corrige el transporte. Comprueba contenido, paquete demo y ensamblado por separado; compilar documentación no demuestra corrección nativa. <a href="./testing.html">Pruebas</a> distingue evidencia de host falso, navegador, Rust y aceptación manual.</p>`,28)])])}const k=a(t,[["render",o]]);export{u as __pageData,k as default};
